const duck = () => (speaking ? 1 - num(D.ttsDucking, 40) / 100 : 1);
function videoVol(item) { return Math.max(0, Math.min(1, num(D.lautstaerke, 80) / 100 * num(D['l_' + item.anim.id], 100) / 100)); }
