// ---------- Namens-Karte ----------
const GIFT_COLORS = { rose: ['#ff2e63', '#ff9ec7'], loewe: ['#ffb300', '#fff1a8'], galaxie: ['#7c4dff', '#4dd0ff'],
  universum: ['#7c4dff', '#ffd54f'], teamherz: ['#ff4f8b', '#ffd54f'], folgen: ['#ff3d7f', '#ff9ec7'] };
function el(t, c, x) { const e = document.createElement(t); if (c) e.className = c; if (x != null) e.textContent = x; return e; }
function showCard(item) {
  const [c1, c2] = GIFT_COLORS[item.anim.id] || [D.nameFarbe1 || '#ff3d7f', D.nameFarbe2 || '#ffb347'];
  const card = el('div', 'card');
  card.style.setProperty('--c1', c1); card.style.setProperty('--c2', c2);
  if (item.avatar && on('profilbildAn')) { const img = el('img', 'avatar'); img.src = item.avatar; img.alt = ''; card.append(img); }
  const name = el('div', 'name');
  const user = String(item.user).slice(0, 24);
  [...user].forEach((ch, i) => { const s = el('span', null, ch === ' ' ? ' ' : ch); s.style.animationDelay = (0.25 + i * 0.045) + 's'; name.append(s); });
  setTimeout(() => name.querySelectorAll('span').forEach(s => s.classList.add('shine')), 900 + user.length * 45);
  if (item.plattform && on('plattformAn', true)) card.prepend(pfBadge(item.plattform));
  card.append(name);
  if (item.text) {
    const sub = el('div', 'sub'); sub.append(document.createTextNode(item.text));
    if (item.amount > 1 || item.key) { item.countEl = el('span', 'count', '× ' + item.amount); sub.append(item.countEl); }
    card.append(sub);
  }
  document.getElementById('cards').append(card);
  let size = 7.2;
  while (name.scrollWidth > innerWidth * 0.86 && size > 3) { size -= 0.3; name.style.fontSize = size + 'vh'; }
  item.card = card;
}
// Plattform-Schild (TikTok / Twitch) – nur Schriftzug und Farben, keine Logos
function pfBadge(p) { const b = el('div', 'pf pf-' + p, PF_NAME[p] || 'TikTok'); return b; }
// Kleines Schild an der Like-Fontäne: „TikTok · Name +12“
let likeTagEl = null, likeTagT = null;
function likeTag(user, n) {
  if (!on('plattformAn', true)) return;
  if (!likeTagEl) { likeTagEl = el('div', 'liketag'); document.body.append(likeTagEl); }
  likeTagEl.replaceChildren(pfBadge('tiktok'), document.createTextNode((user ? String(user).slice(0, 20) + ' ' : '') + '+' + n + ' ❤'));
  likeTagEl.classList.add('show'); clearTimeout(likeTagT); likeTagT = setTimeout(() => likeTagEl.classList.remove('show'), 2500);
}
function updateCount(item) {
  if (!item.countEl) return;
  item.countEl.textContent = '× ' + item.amount;
  item.countEl.style.animation = 'none'; void item.countEl.offsetWidth; item.countEl.style.animation = '';
}

// ---------- Zuordnung Geschenk → Animation ----------
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
function giftAnim(giftName, coinsTotal) {
  const n = norm(giftName);
  const extra = norm(D.eigeneZuordnung).split('\n'); // Format: "geschenkname = animations-id"
  for (const line of extra) { const [g, id] = line.split('=').map(s => s && s.trim()); if (g && id && g === n && entryById(id)) return entryById(id); }
  const direct = LIST.find(a => a.gruppe === 'geschenk' && (a.match || []).some(m => norm(m) === n));
  if (direct && enabled(direct)) return direct;
  const tiers = LIST.filter(a => a.gruppe === 'stufe').map(a => ({ a, ab: num(D['ab_' + a.id], a.ab) })).sort((x, y) => y.ab - x.ab);
  const t = tiers.find(t => coinsTotal >= t.ab);
  return t ? t.a : null;
}

// Weihnachts-Alerts: im Weihnachts-Thema (oder „immer“) laufen die Weihnachts-Versionen (Animations-ID xa-<id>)
const XA_MAP = { 'tw-follow': 'folgen' };
function weihnachtAktiv() {
  const w = D.weihnachtAlerts || 'thema';
  if (w === 'aus') return false; if (w === 'immer') return true;
  return !!curSpiel && /weihnacht|xmas|christmas/i.test((curSpiel.id || '') + ' ' + (curSpiel.name || ''));
}
function festlich(anim) {
  if (!anim || !weihnachtAktiv()) return anim;
  const x = entryById('xa-' + (XA_MAP[anim.id] || anim.id));
  return x && enabled(x) && videoUrl(x) ? x : anim;
}

// ---------- Ereignisse aus Lumia ----------
const TEXT = {
  'tiktok-follower': ['folgen', 'folgt jetzt!'],
  'tiktok-share': ['teilen', 'hat das Live geteilt!'],
  'tiktok-superFan': ['superfan', 'ist jetzt Superfan!'],
  'tiktok-treasureChest': ['schatzkiste', 'wirft eine Schatzkiste!'],
  'tiktok-totalLikes': ['likeziel', 'Like-Ziel erreicht!'],
  'tiktok-battleEnd': ['battle-sieg', 'Battle vorbei!'],
};
function twitchAlert(data, s) {
  const dyn = data.dynamic || {};
  const amount = Number(s.amount || dyn.value || 1) || 1;
  const user = s.displayname || s.username || '';
  const base = { user, avatar: s.avatar, amount: 1, plattform: 'twitch', alert: data.alert, roh: { monate: Number(s.subMonths || (data.dynamic || {}).subMonths || 0), zuschauer: Number(s.viewers || amount) || 0, bits: amount } };
  switch (data.alert) {
    case 'twitch-follower': return { ...base, anim: entryById('tw-follow'), text: D.twTextFollow || 'folgt jetzt!' };
    case 'twitch-subscriber': {
      const plan = String(s.subPlan || s.tier || dyn.value || '');
      if (/prime/i.test(plan)) return { ...base, anim: entryById('tw-primesub'), text: D.twTextPrime || 'abonniert mit Prime 👑' };
      const months = Number(s.subMonths || dyn.subMonths || 0);
      const tier = /3000|tier 3/i.test(plan) ? ' (Tier 3)' : /2000|tier 2/i.test(plan) ? ' (Tier 2)' : '';
      if (months > 1 || dyn.isResub) return { ...base, anim: entryById('tw-resub'), text: (D.twTextResub || 'ist seit {MONATE} Monaten dabei!').replace('{MONATE}', months || '?') + tier };
      if (dyn.isGift) return { ...base, anim: entryById('tw-giftsub'), text: 'verschenkt einen Sub' + tier };
      return { ...base, anim: entryById('tw-sub'), text: (D.twTextSub || 'abonniert!') + tier };
    }
    case 'twitch-giftSubscription': return { ...base, anim: entryById('tw-giftsub'), amount: Number(s.giftAmount || amount) || 1, key: user + '|giftsub', text: D.twTextGift || 'verschenkt Subs' };
    case 'twitch-bits': {
      const t = amount >= num(D.twBitsEpisch, 5000) ? 'tw-bits-episch' : amount >= num(D.twBitsGross, 1000) ? 'tw-bits-gross' : amount >= num(D.twBitsMittel, 100) ? 'tw-bits-mittel' : 'tw-bits-klein';
      return { ...base, anim: entryById(t), text: 'schickt ' + amount + ' Bits' };
    }
    case 'twitch-hypetrainStarted': return { ...base, user: 'HYPE TRAIN', anim: entryById('tw-hypetrain-start'), text: 'ist gestartet! 🚂' };
    case 'twitch-hypetrainLevelProgressed': return { ...base, user: 'HYPE TRAIN', anim: entryById('tw-hypetrain-level'), text: 'Level ' + (s.level || dyn.value || amount) + '!' };
    case 'twitch-hypetrainEnded': return { ...base, user: 'HYPE TRAIN', anim: entryById('tw-hypetrain-ende'), text: 'geschafft – Level ' + (s.level || dyn.value || amount) };
    case 'twitch-raid': return { ...base, anim: entryById('tw-raid'), text: 'raidet mit ' + (s.viewers || amount) + ' Leuten!' };
  }
  return null;
}
// YouTube über Lumia – Schlüssel tolerant erkennen (genaue Lumia-Namen noch ungeprüft)
function ytArt(a) {
  const k = String(a || '').toLowerCase().replace(/^youtube-/, '');
  if (/gift/.test(k) && /member|sponsor|mitglied/.test(k)) return 'geschenk';
  if (/member|sponsor|mitglied/.test(k)) return 'mitglied';
  if (/superchat|super-chat|superch/.test(k)) return 'superchat';
  if (/supersticker|sticker/.test(k)) return 'superchat';
  if (/subscri|abo/.test(k)) return 'abo';
  return '';
}
function ytBetrag(s, dyn) {
  let n = Number(s.amount) || Number(dyn.value) || 0;
  if (!n && s.amountMicros) n = Number(s.amountMicros) / 1e6;
  const anz = String(s.amountDisplayString || s.displayAmount || s.amountDisplay || '');
  if (!n && anz) n = Number(anz.replace(/[^0-9,.]/g, '').replace(',', '.')) || 0;
  const cur = String(s.currency || s.currencySymbol || '€');
  return { n, text: anz || (n ? n.toLocaleString('de-DE', { maximumFractionDigits: 2 }) + ' ' + (cur === 'EUR' ? '€' : cur) : '') };
}
function youtubeAlert(data, s) {
  if (D.ytAn === false) return null;
  const dyn = data.dynamic || {}, art = ytArt(data.alert); if (!art) return null;
  const user = s.displayname || s.username || s.name || '';
  const base = { user, avatar: s.avatar, amount: 1, plattform: 'youtube', alert: data.alert, roh: { art } };
  const anim = (k, v) => entryById(D[k] || v) || entryById(v);
  if (art === 'abo') return { ...base, anim: anim('ytAnimAbo', 'folgen'), text: D.ytTextAbo || 'hat abonniert!' };
  if (art === 'mitglied') { const mo = Number(s.months || s.memberMonths || dyn.months || 0); base.roh.monate = mo;
    return { ...base, anim: anim('ytAnimMitglied', 'superfan'), text: mo > 1 ? 'ist seit ' + mo + ' Monaten Mitglied! 💎' : (D.ytTextMitglied || 'ist jetzt Mitglied! 💎').replace('{MONATE}', mo || '') }; }
  if (art === 'geschenk') { const n = Number(s.giftAmount || s.amount || dyn.value || 1) || 1;
    return { ...base, amount: n, key: user + '|ytgift', anim: anim('ytAnimGeschenk', 'schatzkiste'), text: (D.ytTextGeschenk || 'verschenkt {ANZAHL} Mitgliedschaften!').replace('{ANZAHL}', n) }; }
  const b = ytBetrag(s, dyn); base.roh.betrag = b.text; base.roh.euro = b.n;
  const t = b.n >= num(D.ytScEpisch, 100) ? 'stufe-episch' : b.n >= num(D.ytScGross, 20) ? 'stufe-gross' : b.n >= num(D.ytScMittel, 5) ? 'stufe-mittel' : 'stufe-klein';
  const msg = String(s.message || '').trim();
  let text = (D.ytTextSuperchat || 'schickt einen Super Chat ({BETRAG})').replace('{BETRAG}', b.text || '♥').replace(' ()', '');
  if (msg && D.ytNachricht !== false) text += ' – „' + msg.slice(0, 80) + '“';
  return { ...base, anim: entryById(t), text };
}
function handleAlert(data) {
  const s = data.extraSettings || {};
  if (String(data.alert || '').startsWith('youtube-')) { const it = youtubeAlert(data, s); if (it && it.anim) { it.anim = festlich(it.anim); enqueue(it); } return; }
  if (String(data.alert || '').startsWith('twitch-')) { const it = twitchAlert(data, s); if (it && it.anim) { it.anim = festlich(it.anim); enqueue(it); } return; }
  if (data.alert === 'tiktok-like') { const n = Number(s.amount || s.userLikeCount || (data.dynamic && data.dynamic.value)) || 5; likeBurst(n, true); likeTag(s.username, n); return; }
  if (data.alert === 'tiktok-gift') {
    const amount = Number(s.giftAmount) || 1;
    const coins = (Number(s.coins) || Number(s.value) || 1) * amount;
    if (coins < num(D.minMuenzen, 1)) return;
    const anim = festlich(giftAnim(s.giftName, coins));
    enqueue({ anim, user: s.username, avatar: s.avatar, amount, key: (s.username || '') + '|' + (s.giftName || ''), plattform: 'tiktok', alert: data.alert, roh: { geschenk: s.giftName || 'Geschenk', muenzen: coins },
      text: (D.geschenkText || 'schickt {GESCHENK}').replace('{GESCHENK}', s.giftName || 'ein Geschenk') });
    return;
  }
  const t = TEXT[data.alert];
  if (t) enqueue({ anim: festlich(entryById(t[0])), user: s.username || (data.alert === 'tiktok-totalLikes' ? 'Ihr alle' : ''), avatar: s.avatar, amount: 1, text: t[1], plattform: 'tiktok', alert: data.alert });
}

// Aktionsknöpfe (Aktionszentrale, Lumia-Befehl „Overlay: Inhalt senden“ oder MCP): Inhalt = Animations-ID,
// optional JSON {"id":"airhorn","name":"Sandra","text":"gewinnt!"}
function handleContent(raw) {
  let c = raw; try { c = JSON.parse(raw); } catch (e) { c = { id: String(raw).trim() }; }
  if (String(raw).startsWith('modus:')) { curMode = String(raw).slice(6); spUpdate(); chatUpdate(); return; }
  if (String(raw).startsWith('spiel:')) { try { const alt = curSpiel; curSpiel = JSON.parse(String(raw).slice(6));
    // Jingle beim Wechsel auf ein Spiel/Thema (z. B. Glöckchen beim Weihnachts-Stream) – nicht beim Laden der Quelle
    if (curSpiel && curSpiel.jingle && (!alt || alt.id !== curSpiel.id) && performance.now() > 5000) sfx(curSpiel.jingle, 100); } catch (e) {} try { spUpdate(); chatUpdate(); } catch (e) {} return; }
  if (String(c.id).startsWith('sound:')) { sfx('/sounds/' + String(c.id).slice(6).replace(/[^a-z0-9-]/gi, '') + '.mp3', 100); return; }   // reiner Sound-Knopf
  if (c.id === 'logo') { setLogo(c.an !== false); return; }
  // Chat/Bondrucker: an = true/false erzwingt, null = wie eingestellt; ohne Angabe (alte Lumia-Steuerung) = umschalten
  if (c.id === 'chat') { chatZwang = c.an === undefined ? !chatBox.classList.contains('show') : c.an; chatUpdate(); return; }
  if (c.id === 'streamprint') { spZwang = c.an === undefined ? !spManual : c.an; if (c.an === undefined) spManual = !spManual; spUpdate(); return; }
  if (String(c.id).startsWith('szene:')) { showScene(c.id.slice(6)); return; }
  if (c.id === 'likes') { likeBurst(Number(c.anzahl) || 30); return; }
  const anim = entryById(c.id);
  if (anim) enqueue({ anim, user: c.name || '', text: c.text || '', amount: 1, knopf: true });
}

if (window.Overlay) {
  Overlay.on('alert', handleAlert);
  Overlay.on('overlaycontent', (data) => handleContent(data.content));
}

// ---------- Like-Fontäne ----------
const likeCv = document.getElementById('likes');
const lc = likeCv.getContext('2d');
const parts = [];
const LIKE_COLORS = String(D.likeFarben || '#ff2e63,#ff6fa5,#ff9ec7,#ffd54f,#b388ff').split(',').map(s => s.trim());
function likeResize() { likeCv.width = innerWidth; likeCv.height = innerHeight; }
addEventListener('resize', likeResize); likeResize();
function heart(x, y, s, color, a, rot) {
  lc.save(); lc.translate(x, y); lc.rotate(rot); lc.scale(s, s); lc.globalAlpha = a;
  lc.fillStyle = color; lc.shadowColor = color; lc.shadowBlur = 12;
  lc.beginPath(); lc.moveTo(0, 6);
  lc.bezierCurveTo(-14, -4, -8, -16, 0, -8); lc.bezierCurveTo(8, -16, 14, -4, 0, 6);
  lc.fill(); lc.restore();
}
let likeRunning = false;
function likeLoop() {
  lc.clearRect(0, 0, likeCv.width, likeCv.height);
  for (let i = parts.length - 1; i >= 0; i--) {
    const p = parts[i];
    p.vy += 0.12; p.x += p.vx; p.y += p.vy; p.rot += p.vr; p.life -= 1;
    const a = Math.min(1, p.life / 30);
    heart(p.x, p.y, p.s, p.c, a, p.rot);
    if (p.life <= 0 || p.y > likeCv.height + 40) parts.splice(i, 1);
  }
  if (parts.length) requestAnimationFrame(likeLoop); else { likeRunning = false; lc.clearRect(0, 0, likeCv.width, likeCv.height); }
}
// echt = TikTok-Likes: genau 1 Herz je Like (nacheinander, höchstens likeMax); sonst (Knöpfe, Ansagen) ein Schwall
function likeBurst(count, echt) {
  if (!on('likeAn')) return;
  const eins = echt && D.likeEinsZuEins !== false;
  const n = eins ? Math.min(num(D.likeMax, 60), Math.max(1, Math.round(count)))
    : Math.min(num(D.likeMax, 60), Math.max(4, Math.round(Math.sqrt(count) * 3 * num(D.likeMenge, 1.5))));
  const side = String(D.likePosition || 'rechts');
  const x0 = side === 'links' ? innerWidth * 0.15 : side === 'mitte' ? innerWidth * 0.5 : innerWidth * 0.85;
  if (eins && n > 1) { // gestaffelt, damit man jedes Herz einzeln sieht
    let k = 0; const t = setInterval(() => { likeOne(x0, k++); if (k >= n) clearInterval(t); }, Math.max(40, Math.min(160, 1500 / n)));
    likeOne(x0, k++); return;
  }
  for (let i = 0; i < n; i++) likeOne(x0, i);
}
function likeOne(x0, i) {
  if (parts.length >= 400) return;
  {
    parts.push({ x: x0 + (Math.random() - 0.5) * 40, y: innerHeight + 10,
      vx: (Math.random() - 0.5) * 5, vy: -(innerHeight / 55) * (0.75 + Math.random() * 0.5),
      s: (0.9 + Math.random() * 1.4) * (innerHeight / 900), c: LIKE_COLORS[i % LIKE_COLORS.length],
      rot: (Math.random() - 0.5) * 0.6, vr: (Math.random() - 0.5) * 0.06, life: 90 + Math.random() * 50 });
  }
  if (!likeRunning) { likeRunning = true; requestAnimationFrame(likeLoop); }
}

// ---------- Ansagen ----------
const SCENES = {
  start: ['szeneStart', 'Live startet gleich!', 'Schnapp dir was zu trinken', 0],
  pause: ['szenePause', 'Kurze Pause', 'Bleib dran – gleich geht\'s weiter', 0],
  gleich: ['szeneGleich', 'Gleich geht\'s weiter', 'Nicht weggehen', 0],
  weiter: ['szeneWeiter', 'Weiter geht\'s!', 'Schön, dass du noch da bist', 5],
  ende: ['szeneEnde', 'Danke & bis bald!', 'Folg {KANAL}, dann verpasst du nichts', 0],
  brb: ['szeneBrb', 'Bin gleich zurück!', 'Nicht weggehen – es geht gleich weiter', 0],
  technik: ['szeneTechnik', 'Technische Störung', 'Wir sind gleich wieder da', 0],
};
const VOLLBILD = ['start', 'ende', 'brb', 'technik'];
let countdown = null;
const scene = document.getElementById('scene');
let sceneTimer = null, curSpiel = null;
const sceneBg = document.getElementById('sceneBg'), sceneSpiel = document.getElementById('sceneSpiel');
// Start/Ende passend zum eingestellten Spiel: eigener Text am Spiel › Vorlage mit {SPIEL}, dahinter der Spiel-Hintergrund im Vollbild
function sceneGame(id) {
  const sp = curSpiel && curSpiel.id !== 'standard' ? curSpiel : null;
  // BRB/Technik: eigenes Video aus den Einstellungen, sonst Spiel-Hintergrund; Start/Ende: Spiel-Hintergrund
  const eigenVid = { brb: [D.brbVideo, D.brbVideoQuer], technik: [D.technikVideo, D.technikVideoQuer] }[id];
  const ev = eigenVid && ((FORMAT === 'quer' && eigenVid[1]) || eigenVid[0] || eigenVid[1]);
  const voll = VOLLBILD.includes(id) && D.szeneSpielVollbild !== false;
  const src = !voll ? '' : ev || (sp ? (FORMAT === 'quer' && sp.videoQuer) || sp.video || sp.videoQuer : '');
  if (src) { if (sceneBg.getAttribute('src') !== src) sceneBg.src = src; sceneBg.play().catch(() => {}); } else { sceneBg.pause(); sceneBg.removeAttribute('src'); }
  scene.classList.toggle('voll', !!src);
  const zeile = !sp || !(id === 'start' || id === 'ende') ? '' : String(id === 'start' ? (D.szeneStartSpiel ?? 'Heute: {SPIEL}') : (D.szeneEndeSpiel ?? 'Danke fürs Zuschauen bei {SPIEL}!')).replace(/\{SPIEL\}/g, sp.name);
  sceneSpiel.textContent = zeile; sceneSpiel.style.display = zeile ? '' : 'none';
  const eigen = sp && (id === 'start' ? sp.start : id === 'ende' ? sp.ende : '');
  return eigen || '';
}
function showScene(id) {
  clearTimeout(sceneTimer);
  if (id === 'aus' || !SCENES[id]) { scene.classList.remove('show'); return; }
  const [key, t, s, secs] = SCENES[id];
  const eigen = sceneGame(id);
  const [title, sub] = String(eigen || D[key] || (t + ' | ' + s)).replace(/\{KANAL\}/g, D.bannerText || 'MichaModus').split('|').map(x => x.trim());   // {KANAL} = Name des gewählten Kanals
  document.getElementById('sceneTitle').textContent = title;
  const subEl = document.getElementById('sceneSub'); subEl.textContent = sub || '';
  if (!secs) { const d = document.createElement('span'); d.className = 'dots'; d.innerHTML = '<span>.</span><span>.</span><span>.</span>'; subEl.append(d); }
  // Countdown bei BRB (Minuten aus den Einstellungen, 0 = aus)
  clearInterval(countdown); document.getElementById('sceneUhr').textContent = '';
  const min = id === 'brb' ? num(D.szeneBrbMinuten, 0) : 0;
  if (min > 0) { const ende = Date.now() + min * 60000, uhr = document.getElementById('sceneUhr');
    const tick = () => { const r = Math.max(0, Math.round((ende - Date.now()) / 1000)); uhr.textContent = r ? Math.floor(r / 60) + ':' + String(r % 60).padStart(2, '0') : 'gleich!'; if (!r) clearInterval(countdown); };
    tick(); countdown = setInterval(tick, 1000); }
  scene.classList.toggle('dim', on('szeneAbdunkeln') && !secs);
  scene.classList.add('show'); bannerHype();
  if (id === 'weiter') likeBurst(40);
  if (secs) sceneTimer = setTimeout(() => scene.classList.remove('show'), secs * 1000);
}

window.MM = { handleAlert, handleContent, likeBurst, showScene, busy: () => !!playing || queue.length > 0 || scene.classList.contains('show') };

// ---------- Chat-Einblendung ----------
let chatManual = false, chatZwang = null;
const chatBox = document.getElementById('chat');
const PF_NAME = { tiktok: 'TikTok', twitch: 'Twitch', youtube: 'YouTube', kick: 'Kick', facebook: 'Facebook', trovo: 'Trovo' };
function chatUpdate() {
  const wann = D.chatWann || 'party';
  const show = chatZwang === true || chatZwang === false ? chatZwang : wann === 'immer' || (wann === 'knopf' ? chatManual : wann === artJetzt());
  const aus = D.chatAusrichtung || 'links', br = num(D.chatBreite, 60), rand = num(D.chatX, 4);
  chatBox.classList.toggle('r', aus === 'rechts'); chatBox.classList.toggle('m', aus === 'mitte');
  Object.assign(chatBox.style, { left: (aus === 'rechts' ? Math.max(0, 100 - rand - br) : aus === 'mitte' ? (100 - br) / 2 : rand) + 'vw', top: num(D.chatY, 52) + 'vh', width: num(D.chatBreite, 60) + 'vw', height: num(D.chatHoehe, 30) + 'vh', fontSize: num(D.chatGroesse, 2.2) + 'vh' });
  chatBox.classList.toggle('blasen', D.chatHintergrund !== false);
  chatBox.classList.toggle('show', show);
}
// Logos: Simple Icons (CC0, simpleicons.org) – nur die Pfade, Farbe kommt aus der CSS-Klasse
