function pfIcon(p) {
  const s = document.createElement('span'); s.className = 'pf-icon pf-' + p; s.title = PF_NAME[p] || p;
  s.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="' + PF_ICON[p] + '"/></svg>'; return s;
}
function chatAdd(m) {
  if (m.entfernen) { const x = chatBox.querySelector(`[data-id="${CSS.escape(m.entfernen)}"]`); if (x) x.remove(); return; }
  if (on('chatBefehleWeg', true) && /^\s*!/.test(m.text)) return;
  const row = el('div', 'chat-msg'); row.dataset.id = m.id;
  // Plattform nur als Logo (rundes Abzeichen in Plattformfarbe), ohne Schriftzug; unbekannte Plattform → kurzer Name
  const pf = PF_ICON[m.plattform] ? pfIcon(m.plattform) : el('span', 'pf pf-' + (PF_NAME[m.plattform] ? m.plattform : 'chat'), PF_NAME[m.plattform] || m.plattform || 'Chat');
  const name = el('b', 'chat-name', m.name); if (m.farbe) name.style.color = m.farbe;
  const kopf = el('span', 'chat-kopf'); kopf.append(pf, name);   // Logo und Name bleiben zusammen in einer Zeile
  row.append(kopf, ' ', el('span', 'chat-text', m.text));
  chatBox.append(row);
  while (chatBox.children.length > Math.max(1, num(D.chatMax, 8))) chatBox.firstChild.remove();
  const s = num(D.chatAusblenden, 45);
  if (s > 0) setTimeout(() => { row.classList.add('weg'); setTimeout(() => row.remove(), 600); }, s * 1000);
}
if (window.Overlay) Overlay.on('chat', chatAdd);

// ---------- StreamPrint (virtueller Bondrucker) ----------
let curMode = D.modusStart || 'party', spManual = false, spZwang = null;
// „party“ = Thema ohne Spielfenster (Talk, Party-Bühne, Weihnachten …), „zocken“ = Thema mit Spielfenster
const artJetzt = () => (curMode === 'party' || (curSpiel && curSpiel.ohneFenster) ? 'party' : 'zocken');
const sp = document.getElementById('sp'), spFrame = document.getElementById('spFrame');
// StreamPrint: in der Quer-Quelle eigene Werte (spQ*), wenn „eigene Lage“ an ist
const spG = k => (FORMAT === 'quer' && D.spQEigen !== false && D['spQ' + k] !== undefined && D['spQ' + k] !== '') ? D['spQ' + k] : D['sp' + k];
function spUpdate() {
  const wann = spG('Wann') || 'aus';
  const show = !!D.spUrl && (spZwang === true || spZwang === false ? spZwang : (wann === 'immer' || wann === artJetzt() || (wann === 'knopf' && spManual)));
  if (show && !spFrame.src) spFrame.src = D.spUrl;
  Object.assign(sp.style, { left: num(spG('X'), 3) + 'vw', top: num(spG('Y'), 20) + 'vh', width: num(spG('Breite'), 32) + 'vw', height: num(spG('Hoehe'), 60) + 'vh' });
  sp.style.setProperty('--spR', num(D.spRund, 18) + 'px');
  sp.classList.toggle('rahmen', D.spRahmen !== false);
  sp.classList.toggle('show', show);
}
spUpdate(); chatUpdate();

// ---------- Sounds für Like-Fontäne und Ansagen ----------
let lastLikeSfx = 0;
function sfx(url, vol) {
  if (!url) return;
  try { const a = new Audio(url); a.volume = Math.max(0, Math.min(1, num(D.lautstaerke, 80) / 100 * num(vol, 100) / 100)); a.play().catch(() => {}); } catch (e) {}
}
const _likeBurst = likeBurst;
likeBurst = function (count, echt) {
  if (on('likeAn') && performance.now() - lastLikeSfx > num(D.likeSoundAbstand, 1500)) { lastLikeSfx = performance.now(); sfx(D.likeSound, D.likeSoundLaut); }
  _likeBurst(count, echt);
};
const _showScene = showScene;
showScene = function (id) {
  if (id !== 'aus') sfx(D['sound_' + id], D.szeneSoundLaut);
  _showScene(id);
};
window.MM.likeBurst = likeBurst; window.MM.showScene = showScene;
